SELECT (SELECT group_concat(type||':'||name||':'||tbl_name,'|') FROM (SELECT type,name,tbl_name FROM sqlite_schema WHERE name NOT LIKE 'sqlite_%' ORDER BY type,name)), (SELECT group_concat(cid||':'||name||':'||type||':'||"notnull"||':'||pk,'|') FROM (SELECT cid,name,type,"notnull",pk FROM pragma_table_info('forumpost') ORDER BY cid)), (SELECT group_concat(cid||':'||name||':'||type||':'||"notnull"||':'||pk,'|') FROM (SELECT cid,name,type,"notnull",pk FROM pragma_table_info('blob') ORDER BY cid)), (SELECT group_concat(cid||':'||name||':'||type||':'||"notnull"||':'||pk,'|') FROM (SELECT cid,name,type,"notnull",pk FROM pragma_table_info('event') ORDER BY cid)), (SELECT group_concat(cid||':'||name||':'||type||':'||"notnull"||':'||pk,'|') FROM (SELECT cid,name,type,"notnull",pk FROM pragma_table_info('private') ORDER BY cid)), (SELECT group_concat(seqno||':'||cid||':'||name,'|') FROM (SELECT seqno,cid,name FROM pragma_index_info('forumthread') ORDER BY seqno)), (SELECT group_concat(seqno||':'||cid||':'||name,'|') FROM (SELECT seqno,cid,name FROM pragma_index_info('event_i1') ORDER BY seqno)), (SELECT group_concat(name||':'||"unique"||':'||origin||':'||partial,'|') FROM (SELECT name,"unique",origin,partial FROM pragma_index_list('blob') ORDER BY seq)), (SELECT instr(sql,'length(uuid)>=40 AND rid>0') FROM sqlite_schema WHERE type='table' AND name='blob')